INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695aec0e2cd8c22879dd58a7', '2026-01-04T20:39:10.556Z', '2026-01-05T02:35:00.656Z', 'shaninn123@gmail.com', 'TestX', 'ShiftX', 'TestX — המרת שאלות אמריקאיות לשאלות פתוחות + בדיקת תשובות ע”י AI', 'שאלות אמריקאיות מאפשרות ניחוש, זיהוי תבניות ורמזים בתוך אפשרויות התשובה — ולכן לא תמיד מודדות הבנה אמיתית. המעבר לשאלות פתוחות מעלה משמעותית את איכות המדידה (הנבחן חייב להסביר/לנסח), אך יוצר בעיה תפעולית כבדה: בדיקה ידנית איטית, לא עקבית ולעיתים סובייקטיבית. TestX נועד לפתור את הדילמה: להרוויח את יתרון ההבנה של שאלות פתוחות, בלי לשלם את “מס בדיקת התשובות” באמצעות אוטומציה מבוססת AI.', 'לבנות מודול שמקבל שאלות אמריקאיות (שאלה + תשובה נכונה) וסיכום על החומר, ממיר אותן לשאלות פתוחות שמחייבות ניסוח והבנה, ומפעיל מנוע AI שבודק ומדרג את התשובות הפתוחות באופן עקבי, מוסבר וניתן לבקרה — כך שהארגון לא צריך לבדוק תשובות ידנית.', '1. יצירת “תשובת אמת” וקריטריוני בדיקה (Rubric)
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695aa7ca0831e9ba37d0f6ee', '2026-01-04T15:47:54.268Z', '2026-01-05T02:36:26.673Z', 'shaninn123@gmail.com', 'SkillTrackX - ניהול מעקב התנסויות ומטלות', 'SkillX - הדרכה - סגל', 'SkillTrackX – ניהול ומעקב אחר התנסויות ומטלות הצוער', 'במהלך ההכשרה בבה"ד, כל צוער נדרש לעמוד ברף מסוים של התנסויות (פיקודיות והדרכתיות) ולהגיש שורה של מטלות עיוניות. כיום, המעקב אחר הסטטוס האישי של כל צוער מתפזר בין טבלאות אקסל שונות, מה שמקשה על הקה"דים והסגל לקבל תמונה ברורה: מי כבר התנסה? מי טרם הגיש מטלה? ומי עומד ברף ההכשרה הנדרש? SkillTrackX מרכזת את כלל נתוני ההספק הלימודי והפיקודי במקום אחד.', 'ליצור פלטפורמת WEB לניהול ומעקב אחר "חובות ההכשרה" של הצוער. המערכת תאפשר לסגל הלוגיסטי והפיקודי לשבץ התנסויות, לעקוב אחר הגשת מטלות בזמן אמת, ולהפיק תמונת מצב ויזואלית על כשירות הצוערים למעבר שלבים או סיום הקורס.', '1. ניהול מערך התנסויות 
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695aa5ca5d4e1777d426d57d', '2026-01-04T15:39:22.677Z', '2026-01-05T05:03:55.296Z', 'shaninn123@gmail.com', 'CalX - ייעול תקציב הכשרה', 'GenX', NULL, NULL, NULL, NULL, ARRAY['שון רבנקו','עמרי שור','אלון אקסול','עומרי בר זאב','סמיון גנדל','יהונתן ברדה'], NULL, NULL, NULL, 0, '693b00a201212578d09f8397', false);
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695aa573dcce01c5ede3bb6a', '2026-01-04T15:37:55.122Z', '2026-01-05T04:03:22.742Z', 'shaninn123@gmail.com', ' ControlX - ניהול חלוקת הכיתות בבה״ד 1 + מסדרים (דוח כשירות)', 'SkillX - הדרכה - סגל', ' ControlX - ניהול חלוקת הכיתות בבה״ד 1 + מסדרים', 'בבה״ד 1 הכיתות, האולמות ומרחבי ההדרכה הם משאב מוגבל וקריטי. בפועל, כמות הכיתות הקיימת אינה מספיקה כדי לענות על כלל הדרישות הגדודיות במלואן. במקביל, מסדרי כשירות מתבצעים אך תוצאותיהם אינן תמיד מחוברות ישירות לשיבוץ ולתכנון העתידי. פער זה יוצר ציפיות לא ריאליות, חוסר ודאות, ושינויים מאוחרים בלו״ז.
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a9b557bd8982acc2ff069', '2026-01-04T14:54:45.683Z', '2026-01-05T05:06:00.804Z', 'shaninn123@gmail.com', 'TrackX - נגזרות הדרכה', 'SkillX - הדרכה - סגל', 'TrackX - נגזרות הדרכה', 'בבה״ד 1 נגזרות ההדרכה (התנסויות, מטלות, פעילויות לימודיות) נקבעות ברמה פלוגתית ולעיתים גדודית, אך הבקרה על ביצוען בפועל מתבצעת כיום לא אחיד. מפק״צי הדרכה פלוגתיים מתקשים לבאופן רציף ובזמן אמת האם ההתנסויות והמטלות אכן הועברו על ידי שאר המפק״צים בפלוגה, ובאיזה סטטוס הן נמצאות. המידע מתפזר בין עדכונים בעל־פה, הודעות נקודתיות ומעקב ידני — ללא תמונת מצב רציפה ואמינה.', 'לספק למפק״צ ההדרכה הפלוגתי כלי מרכזי לניהול ומעקב אחר הורדת נגזרות ההדרכה בפלוגה, שבו הוא מגדיר מתי כל התנסות או מטלה אמורה להתבצע, וכל מפק״צ מסמן האם בוצעה בפועל או לא. TrackX נועד לאפשר שקיפות, אחריות ובקרה שוטפת ברמה הפלוגתית, ולהציג למפק״צ ההדרכה הגדודי תמונת מצב מלאה, עדכנית וברורה על כלל הגדוד - ללא צורך באיסוף ידני של נתונים.', '1. ניהול נגזרות הדרכה ברמה פלוגתית
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a9b507571ff48a4c97a79', '2026-01-04T14:54:40.446Z', '2026-01-05T03:01:34.842Z', 'shaninn123@gmail.com', 'SuggestX - הצעה לשינוי ושיפור הלוח זמנים. ודרישה להוספת יחלים', 'SkillX - הדרכה - סגל', 'SuggestX - הצעות לשיפור לוח הזמנים', 'בבה״ד 1 קיימים לוחות זמנים מפורטים לכל פלוגה, אך התכנון בפועל אינו תמיד מתיישב עם המציאות: מחסור בכיתות, חפיפות בין פעילויות, עומסי משאבים, או תכנון שלא לוקח בחשבון אילוצים רוחביים. כיום, הפערים מתגלים רק סמוך לביצוע — כאשר כבר מאוחר לתקן בצורה מיטבית - והשינויים נעשים באופן ידני, נקודתי וללא ראייה מערכתית.', 'למרות שקיימים נתוני לו״ז לכל הפלוגות, אין מנגנון שמצליב אותם עם אילוצי משאבים ומזהה מראש תכנון שאינו בר־ביצוע. כתוצאה מכך:
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a94472b5a63d3e2a18352', '2026-01-04T14:24:39.021Z', '2026-01-05T02:35:08.594Z', 'shaninn123@gmail.com', 'FieldX - מערכת שליטה ובקרה להספקי קליעה וניווט', 'ShiftX', 'FieldX – מערכת שליטה ובקרה להספקי קליעה וניווט', 'אימוני שדה בבה"ד 1 הם ליבת הכשרת הקצין, אך ניהול הנתונים בשטח (תוצאות מטווחים, עמידה בזמני ניווט והספקי הכשרה) מתבצע לעיתים קרובות באופן מבוזר וקשה למעקב בזמן אמת. FieldX נועדה להפוך את ניהול האימון לדיגיטלי וחכם. היא מאפשרת למפקדים בכל הדרגים (מהממ"ש ועד קצין האימונים הגדודי) לראות תמונה מדויקת של קצב ההתקדמות, לאתר עיכובים ולתעד הישגים מקצועיים בצורה פשוטה ונגישה מהשטח.', 'לפתח פלטפורמת WEB אחודה לניהול, תיעוד ובקרה של משבצות אימון (קליעה וניווט). המערכת תאפשר תכנון מוקדם של מטרות האימון, מעקב חי אחר ביצועי הצוערים בשטח, וריכוז נתונים לצורך קבלת החלטות פיקודיות ושיפור רמת הכשירות הגדודית.', 'תכנון והגדרת משבצת אימונים 
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a7ce7512143ee2eb0d958', '2026-01-04T12:44:55.083Z', '2026-01-05T02:47:58.759Z', 'shaninn123@gmail.com', 'PublishX - הנגשת לוח מודעות ', 'SkillX', ' PublishX - לוח מודעות מונגש', 'בבה״ד 1 אין כיום לוח מודעות רשמי, אחיד ומוסכם. בפועל, מידע קריטי — פקודות, שינויים, הנחיות רוחביות והודעות סגל — מתפזר בין קבוצות וואטסאפ רבות, נשלח בזמנים שונים ובפורמטים לא אחידים. הודעות חשובות “נטמעות” בין שיחות, נשלחות מחדש, או לא מגיעות לכל מי שצריך לקבל אותן. מצב זה יוצר חוסר ודאות, טעויות ביצוע, כפילויות ושחיקה — הן אצל הסגל והן אצל הצוערים.', 'לייצר מנגנון מרכזי, אמין ונגיש להפצת הודעות חשובות בבה״ד 1, שישמש כ־Single Source of Truth למידע רוחבי. PublishX נועד לאפשר לכל גורם מורשה (תפקידי רוחב, סגל, פיקוד) לפרסם הודעות בצורה מובנית, מתועדפת וממוקדת — כך שהמידע יגיע בזמן, לגורמים הנכונים, ובצורה שאינה תלויה בשרשורי וואטסאפ.', '1. מקור אמת מרכזי להודעות חשובות
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a7bf2efabfa22e0411044', '2026-01-04T12:40:50.549Z', '2026-01-05T02:50:13.260Z', 'shaninn123@gmail.com', 'FormatX - דמות הקצין לתיקופי התנסויות', 'SkillX', 'FormatX - דמות הקצין', 'במסגרת בה״ד 1, הצגת תוכניות, משימות והתנסויות נעשית לעיתים בפורמטים לא אחידים: מסמכים חופשיים, מצגות שונות, או הסברים בעל־פה. חוסר האחידות מקשה על גורמי האישור להבין במהירות את כוונת המגיש, להעריך סיכונים, להשוות בין חלופות, ולתת החלטה מושכלת. בפועל, חלק גדול מהחיכוך אינו נובע מתוכן חלש — אלא מהיעדר פורמט ברור, עקבי ומצופה מראש.', 'ליצור פורמט אחיד, ברור ומחייב להגשת תוכניות, משימות והתנסויות, בהשראת “דמות הקצין”, המשמש כשפה משותפת בין המגיש לבין גורמי האישור. FormatX נועד להבטיח שכל הצעה מוצגת באופן שלם, ניתן לבחינה ולהשוואה, ומאפשר קבלת החלטות מהירה, עניינית ומבוססת - ללא תלות בסגנון אישי של המגיש.', '1. פורמט מובנה ומחייב להגשה
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a7b9631718c40c2155d74', '2026-01-04T12:39:18.904Z', '2026-01-05T05:12:00.476Z', 'shaninn123@gmail.com', 'SimX - סימולציות', 'GenX', 'SimX - פלטפורמה חכמה לניהול למידה והתאמת סימולציות', 'בעולם ההכשרה בבה"ד, הסימולציה היא אחד הכלים האפקטיביים ביותר ללמידה. עם זאת, כיום חלק גדול מהתובנות הולך לאיבוד בין מחזורים, והתאמת הסימולציה לצוער נעשית לרוב באופן ידני ומבוסס זיכרון. SimX הופכת את עולם הסימולציות מ"אירוע חולף" לנכס אסטרטגי. המערכת מאפשרת לשמר ידע ממחזור למחזור, לבצע התאמה אישית מדויקת של התרחיש לצוער, ולייצר תמונת מצב פיקודית על איכות הלמידה והפערים המקצועיים בשטח.', 'לפתח פלטפורמה לניהול ידע ובקרה פדגוגית עבור מרכז הסימולציות. המערכת נועדה לייעל את תהליך התאמת הסימולציה לפרופיל הצוער, לרכז את התיעוד והתחקור במקום אחד, ולאפשר למידה רוחבית של הסגל והצוערים על ידי הפיכת משובים ולקחים לנתונים נגישים וניתנים לניתוח.', '1. ניהול מאגר סימולציות חכם 
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a7b755e0b0088692c48d2', '2026-01-04T12:38:45.095Z', '2026-01-05T02:36:04.380Z', 'shaninn123@gmail.com', 'VerifyX - תיקוף התנסויות', 'GenX', 'VerifyX – המערכת לתיקוף וטיוב התנסויות ההכשרה', 'תכני ההכשרה בבה"ד חייבים להשתנות בקצב של השטח. לעיתים קרובות, נוצר פער בין מה שכתוב במערכי ההתנסות לבין הרלוונטיות שלהם למגמות השונות (למשל: הבדלים בין מגמת "נחשון" למגמת "מומחים") או למציאות המבצעית המשתנה. VerifyX מעניקה לצוערים את הכוח להציף פערים בזמן אמת, והופכת את המפקץ למנהל תוכן דינמי שמתקן ומשפר את ההכשרה תוך כדי תנועה.', 'ליצור ערוץ תקשורת ישיר ודיגיטלי לתיקוף איכות התכנים. המערכת תאפשר לצוערים לדווח על חוסר רלוונטיות, פערים מקצועיים או צורך בהתאמות מגזריות בהתנסויות, ותעניק למפקצים כלי ניהולי למעקב אחר הדיווחים, ביצוע תיקונים ושיפור מתמיד של מערכי ההכשרה.', '1. ממשק הצפת פערים 
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a7a0abb1e074ac5981a39', '2026-01-04T12:32:42.105Z', '2026-01-04T12:32:42.105Z', 'shaninn123@gmail.com', 'MikraotX', 'MikarotX', NULL, NULL, NULL, NULL, ARRAY[]::text[], NULL, NULL, NULL, 0, '693b00a201212578d09f8397', false);
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a79d016dc6a51b656ee4a', '2026-01-04T12:31:44.946Z', '2026-01-05T05:37:40.147Z', 'shaninn123@gmail.com', 'KnowX - שימור ידע', 'GenX', 'KnowX – הפלטפורמה המרכזית לשימור ידע ותחקור', 'בסביבה דינמית כמו בה"ד 1, ידע רב הולך לאיבוד עם תחלופת המחזורים והסגל. לקחים שנלמדו בקושי רב במחזור אחד "נשכחים" במחזור הבא, וטעויות חוזרות על עצמן. KnowX נועדה להיות ה"ויקיפדיה" של הבה"ד – מקום אחד שמרכז מערכי שיעור, דגשים פדגוגיים ותחקורי התנסויות, כדי שכל בעל תפקיד יוכל להתחיל את תפקידו מהנקודה שבה קודמו סיים.', 'הקמת מאגר ידע דיגיטלי, שיתופי וחכם, המאפשר לסגל ולצוערים להעלות תכנים מקצועיים, לקחים מהתנסויות ודגשי הדרכה. המערכת תאפשר חיפוש מהיר ושליפת מידע רלוונטי לפי תפקיד, סוג אירוע או תחום מקצועי, במטרה לשפר את איכות ההכשרה ולמנוע "המצאה מחדש של הגלגל".', '1. בנק מערכי שיעור ודגשי הדרכה
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a78749ec89c9d1bed13ab', '2026-01-04T12:25:56.571Z', '2026-01-05T02:11:37.783Z', 'shaninn123@gmail.com', 'CrackX - תקיפה והגנה', 'GenX', NULL, NULL, NULL, NULL, ARRAY['אורי דאבוש','אייל גורן','יותם סופר','Michael Adar','מיכאל זסלבסקי','ניצן קפמן רז','עומר בלס','רועי סולד','דניאל רוזנפלד'], NULL, NULL, NULL, 0, '693b00a201212578d09f8397', false);
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a786c9939f8a47c12775e', '2026-01-04T12:25:48.275Z', '2026-01-05T05:11:36.490Z', 'shaninn123@gmail.com', 'BotX - בוט מקשר בין עידכונים לווצאפ', 'GenX', 'BotX - בוט מקשר בין עידכונים לווצאפ', 'כיום רוב המידע הקריטי של הצוער והסגל נמצא ב"מגדלור", אך הגישה אליו דורשת כניסה יזומה לאתר, הזדהות וניווט בתפריטים. בעולם שבו הלו"ז צפוף והזמן יקר, אנחנו רוצים שהמידע יגיע אל המשתמש במקום שבו הוא נמצא הכי הרבה – הוואטסאפ. BotX הוא הגשר החכם בין מערכות הבה"ד לבין המשתמש, שהופך את הממשק הארגוני לשיחה פשוטה, נגישה ומהירה.', 'לפתח בוט וואטסאפ עוצמתי המחובר למערכות המידע (API) של הבה"ד. הבוט ישמש כ"זרוע הביצועית" וההתראתית של אתר המגדלור, ינגיש מידע בזמן אמת (סקרים, מטלות, תורנויות) ויאפשר ביצוע פעולות ישירות מתוך הצ''אט, תוך שמירה על אבטחת מידע וניהול הרשאות קפדני.', '1. מנוע התראות חכם 
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a776f40c0e1223480536b', '2026-01-04T12:21:35.415Z', '2026-01-05T02:42:07.388Z', 'shaninn123@gmail.com', 'CalendX - ניהול שוטף של הלוח זמנים, עם עידכונים בזמן אמת של שינויים', 'SkillX', 'CalendX - ניהול שוטף של לוח זמנים עם עדכונים בזמן אמת', 'לוחות זמנים בבה״ד 1 משתנים באופן תדיר: פעילויות זזות, מתבטלות או מתווספות בהתראה קצרה, משאבים משתנים, ואילוצים חיצוניים משפיעים על התכנון המקורי. בפועל, הלוז הרשמי מתיישן מהר מאוד, והמידע העדכני “מתפצל” בין הודעות, שיחות, קבוצות וגורמים שונים. מצב זה יוצר בלבול, חוסר תיאום, טעויות ביצוע ופגיעה באמון המשתמשים בלו”ז כגורם אמת.', 'לספק מערכת לניהול שוטף של לוח זמנים דינמי, המשמשת כ־Single Source of Truth, ומאפשרת עדכון, הפצה והצגה של שינויים בזמן אמת לכל הגורמים הרלוונטיים. המערכת נועדה להבטיח שכל משתמש פועל על בסיס אותו מידע עדכני, תוך תיעוד שינויים, הבנת השפעתם, וצמצום חיכוך תפעולי הנובע מאי־ודאות בלו”ז.', '1. לוח זמנים מרכזי ואחיד
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a771dc80be18c736513b4', '2026-01-04T12:20:13.478Z', '2026-01-05T02:50:01.363Z', 'shaninn123@gmail.com', 'CampusX', 'SkillX', 'CampusX ', 'מערכת Campus משמשת כפלטפורמה רשמית להגשת מטלות ולמעקב לימודי, אך בפועל ההתממשקות אליה מורכבת, מסורבלת ואינה מותאמת לצרכים התפעוליים והפיקודיים של הסגל. תהליכים כמו פתיחת מטלה, מעקב אחרי הגשות, זיהוי פערים, ומתן תמונת מצב עדכנית דורשים מאמץ ידני רב ולעיתים אינם מספקים שקיפות מספקת בזמן אמת. כתוצאה מכך, נוצר נתק בין ההגשה הפורמלית לבין היכולת של הסגל לנהל, לעקוב ולהגיב בצורה יעילה.', 'לפתח מערכת פנימית, בשליטה מלאה של הארגון, שתאפשר הגשת מטלות ומעקב אחריהן בצורה פשוטה, ברורה ונגישה, ותשמש כלי עבודה יומיומי לסגל. המערכת נועדה להקל על תהליך ההגשה עבור הצוערים, ולספק לסגל יכולת מעקב, בקרה וזיהוי פערים בזמן אמת — ללא תלות במורכבות או מגבלות של מערכת חיצונית.', '1. שליטה מלאה במערכת ובתהליכים
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a73bf7f0715487d370b5f', '2026-01-04T12:05:51.248Z', '2026-01-05T02:39:32.364Z', 'shaninn123@gmail.com', 'InsightX - מעקב חכם ולומד של משובים חמים', 'SkillX', 'InsightX - מעקב חכם ולומד של משובים חמים', 'משובים חמים נאספים בבה״ 1 באופן תדיר – לאחר התנסות, משימה, או אינטראקציה משמעותית. למרות הערך הפוטנציאלי הגבוה שלהם, ברוב המקרים הם נותרים כטקסט חופשי, רגשי ולא מובנה, שאינו מאפשר זיהוי דפוסים, תעדוף בעיות או למידה מערכתית לאורך זמן. העומס האנושי הנדרש לניתוח המשובים מוביל לכך שחלקם הגדול אינו מטופל, וחלק אחר מטופל נקודתית ללא סגירת מעגל. כתוצאה מכך נפגעים הן איכות קבלת ההחלטות והן אמון המשתמשים בתהליך המשוב.', 'להקים מערכת חכמה ולומדת שמאפשרת קליטה, הבנה וניתוח של משובים חמים בזמן אמת, והפיכתם ממידע גולמי ולא מובנה לתובנות מערכתיות ברות־פעולה. InsightX נועד לאפשר לארגון ללמוד ממשובים לאורך זמן, לזהות מגמות חוזרות, לאתר חריגות מוקדם, ולסגור מעגל בין משוב, טיפול ושיפור – ללא תלות בניתוח ידני שוטף.', '1. קליטת משובים חופשיים בזמן אמת
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a73b2be32a758f8fdbdca', '2026-01-04T12:05:38.517Z', '2026-01-05T02:39:39.152Z', 'shaninn123@gmail.com', 'PollX - סקרים וניהולם', 'SkillX', 'PollX – הפלטפורמה האחודה לסקרים', 'במהלך ההכשרה בבה"ד, הצוערים נדרשים למלא עשרות סקרים ודיווחים – החל מתחקור שבועי ועד מילוי ימי הולדת. כיום, המידע מבוזר בקישורים שונים בווטסאפ, נתונים הולכים לאיבוד, והקה"דים משקיעים שעות בניתוח ידני של מלל חופשי לצורך הכנת מצגות תחקור. PollX מרכזת את כלל הסקרים תחת קורת גג אחת, מעניקה שקיפות מלאה לצוער והופכת את איסוף הנתונים לאוטומציה חכמה שחוסכת זמן יקר לסגל.', 'ליצור "תחנה אחת" לכלל הסקרים והדיווחים בקורס. המערכת נועדה לשפר את חוויית הצוער באמצעות אזור אישי שקוף, ולספק לסגל כלי ניתוח מתקדמים המבוססים על בינה מלאכותית (לניתוח טקסט) ומחולל מצגות אוטומטי לקיצור תהליכי התחקור.', '1. אזור אישי לצוער
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a7340a033d408ed45307b', '2026-01-04T12:03:44.700Z', '2026-01-05T02:35:17.134Z', 'shaninn123@gmail.com', 'RasariX - תקלות בינוי', 'LogiX', 'RasariX – ניהול מערך הרס"ר, הבינוי והניקיון בבה"ד', 'תחזוקת הבה"ד ונראותו היא משימה סיזיפית הדורשת סנכרון הדוק בין רס"רים, קה"דים, קל"פים וצוערים. כיום, ניהול מסדרי הניקיון ודיווח על תקלות בינוי מתבסס על קבוצות וואטסאפ עמוסות, גיליונות אקסל ידניים ודיווחים שנוטים ללכת לאיבוד. RasariX נועדה לעשות סדר ב"עולם המשמעת והתחזוקה", ולהפוך את העבודה מול הרס"ר למבוקרת, שקיפה ודיגיטלית לחלוטין.', 'לפתח פלטפורמת WEB אחודה לניהול שיטתי של מסדרי גזרות, מסדרי כיתות ומעקב אחר תקלות בינוי ותשתיות. המערכת תאפשר לסגל הלוגיסטי (קה"דים וקל"פים) לקבל משימות ברורות, להעלות הוכחות ביצוע (תמונות) ולקבל אישור מהרס"ר בזמן אמת, תוך ניטור דחיפות תקלות הבינוי והבטחת רמת תחזוקה גבוהה בבה"ד.', '1. ניהול גזרות ומסדרי כיתות
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a72d2c8624c98a3936ac5', '2026-01-04T12:01:54.120Z', '2026-01-05T02:35:24.853Z', 'shaninn123@gmail.com', 'ShuttleX - שאטלים וניהולם', 'LogiX', 'ShuttleX – מערכת חכמה לניהול מערך ההיסעים והשאטלים', 'ניהול לוגיסטי של מאות צוערים היוצאים הביתה/מגיעים לבה"ד דורש דיוק מרבי בתכנון אוטובוסים, תחנות ושיבוצי מקומות. כיום, איסוף הנתונים והשיבוץ מתבצעים לרוב ידנית, מה שמוביל לאוטובוסים חצי ריקים מחד או למחסור במקומות מאידך. ShuttleX נועדה לייצר תהליך אוטומטי מקצה לקצה: מהגדרת קווי הנסיעה על ידי הקל"ג, דרך בחירת התחנה על ידי הצוער, ועד להפקת רשימות עלייה לאוטובוס בלחיצת כפתור.', 'ליצור פלטפורמת WEB לניהול רישום ושיבוץ צוערים לשאטלים. המערכת תבצע אופטימיזציה של מקומות הישיבה בהתאם לביקוש, תמנע רישום כפול ותספק לסגל הלוגיסטי תמונת מצב עדכנית וקובץ שיבוץ סופי ומאורגן לכל אוטובוס.', '1. ניהול מערך ההיסעים
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a72b9d493148d1e82555d', '2026-01-04T12:01:29.362Z', '2026-01-05T05:03:43.366Z', 'shaninn123@gmail.com', 'SupplyX - ניהול רספיה', 'LogiX', 'SupplyX - ניהול רספיה', 'ניהול לוגיסטי בבה"ד הוא אתגר דינמי הדורש דיוק מקסימלי תחת עומס. כיום, המעקב אחר ציוד ברס"פיות ובמחסנים נסמך לעיתים קרובות על רישום ידני, זיכרון אנושי או טבלאות מבוזרות. מצב זה מוביל לאובדן ציוד, חוסר ודאות לגבי זמינות פריטים קריטיים וקושי בקבלת החלטות בזמן אמת. SupplyX נועדה לעשות סדר בשרשרת האספקה היחידתית, להחליף את הנייר בדיגיטל חכם ולהפוך את הצוער הלוגיסטי למנהל נתונים מתקדם.', 'ליצור מערכת WEB אחודה המהווה "מקור אמת" לכלל הציוד בבה"ד. המערכת תאפשר לצוערים, לסגל הלוגיסטי ולמפקדים לנהל מעקב שיטתי, מבוקר ואחיד אחר השאלות, ניפוקים, מלאי וחוסרים תוך הצגת תמונת מצב עדכנית בכל רגע נתון וצמצום משמעותי של "אובדן הציוד" הצה"לי.', '1. ניהול מחסן ורס"פיה
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a6e156dce8474acfbeb57', '2026-01-04T11:41:41.958Z', '2026-01-05T02:34:51.186Z', 'shaninn123@gmail.com', 'FairX - טבלת צדק', 'ShiftX', 'FairX - מודול תורנויות לשיבוץ אוטומטי והוגן באמצעות “טבלת צדק”', 'שיבוץ תורנויות ידני הוא אחד המקורות המרכזיים לחיכוך ארגוני: תחושת חוסר הוגנות, טעויות אנוש, עומס על המפקדים, וערעור אמון מצד הצוערים. המורכבות גדלה כאשר קיימים פטורים משתנים (רפואיים, אישיים, תפקידיים), אילוצי לו”ז, סוגי משמרות שונים והיסטוריית תורנויות קודמת. FairX נועד להחליף שיבוץ ידני ושרירותי במנגנון חכם, שקוף ועקבי, המבטיח חלוקה הוגנת לאורך זמן — ולא רק “סגירת חורים” נקודתית.', 'לתכנן ולפתח מודול תוכנה אוטומטי לשיבוץ תורנויות, המופעל באמצעות אלגוריתם “טבלת צדק”, המבצע הקצאה הוגנת של צוערים למשמרות בהתאם לפטורים מעודכנים, היסטוריית שירות, ואילוצים תפעוליים — תוך שקיפות מלאה ויכולת בקרה ניהולית.', '1. שיבוץ אוטומטי והוגן 
INSERT INTO hackalon_team (id, created_date, updated_date, created_by, name, department_name, problem_name, problem_intro, problem_objective, problem_requirements, member_names, specification_deadline, specification_template_url, final_product_deadline, "order", created_by_id, is_sample) VALUES ('695a6779c352dd5b004c3f83', '2026-01-04T11:13:29.594Z', '2026-01-05T05:25:08.818Z', 'shaninn123@gmail.com', 'WashX - ניהול מכונות כביסה', 'ShiftX', 'WashX - מערכת חכמה לניהול תורים, מכונות כביסה וייבוש בבה״ד 1', 'חדרי כביסה משותפים סובלים משילוב קבוע של עומס, חוסר ודאות והתנהגות אנושית לא צפויה: שריונים שלא מתממשים, מכונות שנתקעות “תפוסות” למרות שסיימו, חוסר סנכרון בין כביסה לייבוש, ותלות גבוהה בהתערבות ידנית של גורמי ניהול. כאשר המערכת נדרשת לשרת לא רק חדר אחד אלא מספר חדרים וגדודים תחת ניהול מרכזי — המורכבות גדלה משמעותית. WashX נועד לייצר סדר, שקיפות ואוטומציה בעולם כאוטי מטבעו.', 'לתכנן ולפתח פלטפורמת WEB אחודה, פשוטה לשימוש אך עשירה לוגית, לניהול תורים ושריונים למכונות כביסה וייבוש, עם ניטור סטטוסים בזמן אמת, התראות חכמות, ויכולת התרחבות לחדרים ויחידות מרובות תחת שליטה מרכזית.', '1. ניהול תורים ושריונים חכם
